 1→import * as fs from 'fs';
 2→import * as path from 'path';
 3→import * as yaml from 'js-yaml';
 4→import { ScenarioFile } from './types';
 5→
 6→export function loadScenarioFile(filePath: string): ScenarioFile {
 7→  const content = fs.readFileSync(filePath, 'utf-8');
 8→  const parsed = yaml.load(content) as ScenarioFile;
 9→
10→  if (!parsed || !Array.isArray(parsed.scenarios)) {
11→    throw new Error(`Invalid scenario file: ${filePath} — missing "scenarios" array`);
12→  }
13→
14→  for (const scenario of parsed.scenarios) {
15→    if (!scenario.name || !Array.isArray(scenario.steps)) {
16→      throw new Error(`Invalid scenario in ${filePath} — each scenario needs "name" and "steps"`);
17→    }
18→  }
19→
20→  return parsed;
21→}
22→
23→export function loadAllScenarios(scenariosDir: string): { file: string; data: ScenarioFile }[] {
24→  const files = fs.readdirSync(scenariosDir).filter(f => f.endsWith('.yaml') || f.endsWith('.yml'));
25→
26→  if (files.length === 0) {
27→    throw new Error(`No YAML files found in ${scenariosDir}`);
28→  }
29→
30→  return files.map(file => ({
31→    file,
32→    data: loadScenarioFile(path.join(scenariosDir, file)),
33→  }));
34→}
