265→            onUpload={handleFileUpload}
266→            onLoadSample={handleLoadSample}
267→          />
268→        </div>
269→      ) : (
270→        <div className="app__editor-wrapper">
271→          <div className="app__header">
272→            <h1 className="app__title">{t('appTitle')}</h1>
273→            <div className="app__header-actions">
274→              <button
275→                className="app__lang-toggle"
276→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
277→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
278→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
279→              >
280→                {language === 'en' ? 'EN' : '中'}
281→              </button>
282→              <button
283→                className="app__theme-toggle"
284→                onClick={toggleTheme}
285→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
286→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
287→              >
288→                {themeIcon}
289→              </button>
290→              <button
291→                className="app__agent-toggle"
292→                onClick={handleAgentToggle}
293→              >
294→                {t('agentMode')}
295→              </button>
296→            </div>
297→          </div>
298→          <div className="app__mode-header">
299→            <span className="app__mode-title">{t('editorMode')}</span>
300→          </div>
301→          {errorMessage && (
302→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
303→          )}
304→          <main className="app__main">
305→            {tables.length === 0 ? (
306→              <div className="app__empty">
307→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
308→              </div>
309→            ) : (
310→              <>
311→                <QueryEditor
312→                  onExecute={handleQueryExecute}
313→                  initialQuery={editorQuery}
314→                />
315→                {queryResult?.resultType === 'markdown' ? (
316→                  <ResultMarkdown result={queryResult} />
317→                ) : (
318→                  <ResultsTable result={queryResult} />
319→                )}
320→              </>
321→            )}
322→          </main>
323→        </div>
324→      )}
325→    </div>
326→  );
327→}
328→
329→export default function App() {
330→  const sessionId = useSessionId();
331→  const [tables, setTables] = useState<TableInfo[]>([]);
332→  const [loading, setLoading] = useState(true);
333→  const [error, setError] = useState<string | null>(null);
334→  const refreshTables = useCallback(async () => {
335→    try {
336→      const response = await fetch('/api/tables', {
337→        headers: { 'X-Session-ID': sessionId },
338→      });
339→      if (!response.ok) throw new Error('Failed to fetch tables');
340→      const data = await response.json();
341→      setTables(data);
342→    } catch (e) {
343→      console.error('Failed to refresh tables:', e);
344→    }
345→  }, [sessionId]);
346→
347→  useEffect(() => {
348→    (async () => {
349→      try {
350→        const response = await fetch('/api/health');
351→        if (!response.ok) throw new Error('Backend is not available');
352→        await refreshTables();
353→      } catch (e) {
354→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
355→      } finally {
356→        setLoading(false);
357→      }
358→    })();
359→  }, [refreshTables]);
360→
361→  if (loading) {
362→    return <div className="app-loading">Connecting to backend...</div>;
363→  }
364→
365→  if (error) {
366→    return (
367→      <div className="app-error">Failed to connect: {error}</div>
368→    );
369→  }
370→
371→  return (
372→    <ConfigProvider>
373→      <LanguageProvider>
374→        <ThemeProvider>
375→          <AgentProvider refreshTables={refreshTables}>
376→            <AppContent tables={tables} refreshTables={refreshTables} sessionId={sessionId} />
377→          </AgentProvider>
378→        </ThemeProvider>
379→      </LanguageProvider>
380→    </ConfigProvider>
381→  );
382→}
